const UNIDADES = ['', 'uno', 'dos', 'tres', 'cuatro', 'cinco', 'seis', 'siete', 'ocho', 'nueve', 'diez', 'once', 'doce', 'trece', 'catorce', 'quince', 'dieciséis', 'diecisiete', 'dieciocho', 'diecinueve', 'veinte', 'veintiuno', 'veintidós', 'veintitrés', 'veinticuatro', 'veinticinco', 'veintiséis', 'veintisiete', 'veintiocho', 'veintinueve'];
const DECENAS = ['', '', '', 'treinta', 'cuarenta', 'cincuenta', 'sesenta', 'setenta', 'ochenta', 'noventa'];
const CENTENAS = ['', 'ciento', 'doscientos', 'trescientos', 'cuatrocientos', 'quinientos', 'seiscientos', 'setecientos', 'ochocientos', 'novecientos'];
const MESES_KIT = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];

function menorMil(n) {
  if (n === 0) return '';
  if (n === 100) return 'cien';
  const c = Math.floor(n / 100); const r = n % 100;
  let t = CENTENAS[c];
  if (r) {
    const dec = r < 30 ? UNIDADES[r] : `${DECENAS[Math.floor(r / 10)]}${r % 10 ? ` y ${UNIDADES[r % 10]}` : ''}`;
    t = t ? `${t} ${dec}` : dec;
  }
  return t;
}
export function numeroALetras(numero) {
  const n = Math.floor(Math.abs(Number(numero) || 0));
  if (n === 0) return 'cero';
  const millones = Math.floor(n / 1000000); const miles = Math.floor((n % 1000000) / 1000); const resto = n % 1000;
  const partes = [];
  if (millones) partes.push(millones === 1 ? 'un millón' : `${menorMil(millones).replace(/uno$/, 'un')} millones`);
  if (miles) partes.push(miles === 1 ? 'mil' : `${menorMil(miles).replace(/uno$/, 'un').replace(/veintiuno$/, 'veintiún')} mil`);
  if (resto) partes.push(menorMil(resto));
  return partes.join(' ');
}
const capitalizar = (t) => t.split(' ').map((p) => (p === 'y' ? p : p.charAt(0).toUpperCase() + p.slice(1))).join(' ');
const fmt2 = (n) => Number(n).toLocaleString('es-VE', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

/* "Ciento Treinta Bolívares con 00/100 (Bs. 130,00)" */
export function montoEnLetras(monto, singular = 'Bolívar', plural = 'Bolívares', simbolo = 'Bs.') {
  const m = Math.round(Number(monto || 0) * 100) / 100;
  const entero = Math.floor(m); const cent = Math.round((m - entero) * 100);
  const letras = capitalizar(numeroALetras(entero).replace(/uno$/, 'un'));
  return `${letras} ${entero === 1 ? singular : plural} con ${String(cent).padStart(2, '0')}/100 (${simbolo} ${fmt2(m)})`;
}
export function dolaresEnLetras(monto, mayusculas = false) {
  const entero = Math.round(Number(monto || 0));
  const t = `${capitalizar(numeroALetras(entero).replace(/uno$/, 'un'))} Dólares Americanos`;
  return mayusculas ? `${t.toUpperCase()} ($${fmt2(entero)})` : `${t} (USD ${entero})`;
}
export function fechaNum(iso) { return iso ? `${iso.slice(8, 10)}/${iso.slice(5, 7)}/${iso.slice(0, 4)}` : ''; }
/* "a los veinticinco (25) días del mes de septiembre del año dos mil veintiséis (2026)" */
export function fechaFirmaLetras(iso) {
  if (!iso) return '';
  const d = Number(iso.slice(8, 10)); const m = Number(iso.slice(5, 7)); const y = Number(iso.slice(0, 4));
  const dia = d === 1 ? 'al primer (1er) día' : `a los ${numeroALetras(d)} (${d}) días`;
  return `${dia} del mes de ${MESES_KIT[m - 1]} del año ${numeroALetras(y)} (${y})`;
}
/* "23 de junio del 2026" */
export function fechaLarga(iso) { return iso ? `${iso.slice(8, 10)} de ${MESES_KIT[Number(iso.slice(5, 7)) - 1]} del ${iso.slice(0, 4)}` : ''; }
/* "veintiún (21)" */
export function diaEnLetras(d) { const n = Number(d); return `${numeroALetras(n).replace(/veintiuno$/, 'veintiún').replace(/^uno$/, 'un')} (${n})`; }
export function partesFecha(iso) { return iso ? { dia: String(Number(iso.slice(8, 10))), mes: MESES_KIT[Number(iso.slice(5, 7)) - 1], anio: iso.slice(0, 4) } : { dia: '', mes: '', anio: '' }; }
/* "V- 31.027.751" */
export function cedulaLegal(ced) {
  const m = String(ced || '').match(/^\s*([VEve])?\s*-?\s*([\d.]+)\s*$/);
  if (!m) return String(ced || '');
  const num = Number(m[2].replace(/\./g, ''));
  return `${(m[1] || 'V').toUpperCase()}- ${num.toLocaleString('de-DE')}`;
}

